2	use std::ops::Add;
3	use std::slice;
4	
5	use comemo::Tracked;
6	use ecow::{EcoString, EcoVec, eco_format, eco_vec};
7	use typst_syntax::{Span, Spanned};
8	
9	use crate::diag::{At, SourceDiagnostic, SourceResult, StrResult, bail, error};
10	use crate::engine::Engine;
11	use crate::foundations::{
12	    Array, Context, Dict, FromValue, Func, IntoValue, Repr, Str, Value, cast, func, repr,
