457	impl Repr for Args {
458	    fn repr(&self) -> EcoString {
459	        let pieces = self.items.iter().map(Arg::repr).collect::<Vec<_>>();
460	        eco_format!("arguments{}", repr::pretty_array_like(&pieces, false))
461	    }
