264	            FuncInner::With(with) => with.0.keywords(),
265	        }
266	    }
267	
268	    /// Where the function is defined in the Rust source code (only `Some(_)` if
269	    /// it is native, and even then it can be `None` if the function is
270	    /// generated, like the typed HTML API).
271	    pub fn def_site(&self) -> Option<DefSite> {
272	        match &self.inner {
273	            FuncInner::Native(native) => native.def_site,
274	            FuncInner::Element(elem) => Some(elem.def_site()),
275	            _ => None,
276	        }
277	    }
278	
279	    /// The function's associated scope of sub-definition.
280	    pub fn scope(&self) -> Option<&'static Scope> {
281	        match &self.inner {
282	            FuncInner::Native(native) => Some(&native.0.scope),
283	            FuncInner::Element(elem) => Some(elem.scope()),
284	            FuncInner::Closure(_) => None,
285	            FuncInner::Plugin(_) => None,
286	            FuncInner::With(with) => with.0.scope(),
287	        }
288	    }
289	
290	    /// Get a field from this function's scope, if possible.
291	    pub fn field(
292	        &self,
293	        field: &str,
294	        sink: impl WarningSink,
295	    ) -> StrResult<&'static Value> {
296	        let scope =
297	            self.scope().ok_or("cannot access fields on user-defined functions")?;
298	        match scope.get(field) {
299	            Some(binding) => Ok(binding.read_checked(sink)),
300	            None => match self.name() {
301	                Some(name) => bail!("function `{name}` does not contain field `{field}`"),
302	                None => bail!("function does not contain field `{field}`"),
303	            },
304	        }
305	    }
306	
307	    /// Extract the element function, if it is one.
308	    pub fn to_element(&self) -> Option<Element> {
309	        match self.inner {
310	            FuncInner::Element(func) => Some(func),
311	            _ => None,
312	        }
313	    }
314	
315	    /// Extract the plugin function, if it is one.
316	    pub fn to_plugin(&self) -> Option<&PluginFunc> {
317	        match &self.inner {
318	            FuncInner::Plugin(func) => Some(func),
319	            _ => None,
320	        }
321	    }
322	
323	    /// Call the function with the given context and arguments.
324	    pub fn call<A: IntoArgs>(
325	        &self,
326	        engine: &mut Engine,
327	        context: Tracked<Context>,
328	        args: A,
329	    ) -> SourceResult<Value> {
330	        self.call_impl(engine, context, args.into_args(self.span))
331	    }
332	
333	    /// Non-generic implementation of `call`.
334	    #[typst_macros::time(name = "func call", span = self.span())]
335	    fn call_impl(
336	        &self,
337	        engine: &mut Engine,
338	        context: Tracked<Context>,
339	        mut args: Args,
340	    ) -> SourceResult<Value> {
341	        match &self.inner {
342	            FuncInner::Native(native) => {
343	                let value = (native.function.0)(engine, context, &mut args)?;
344	                args.finish()?;
345	                Ok(value)
346	            }
347	            FuncInner::Element(func) => {
348	                let value = func.construct(engine, &mut args)?;
349	                args.finish()?;
350	                Ok(Value::Content(value))
351	            }
352	            FuncInner::Closure(closure) => (engine.library.routines.eval_closure)(
353	                self,
354	                closure,
355	                engine.world,
356	                engine.library,
357	                engine.introspector.into_raw(),
358	                engine.traced,
359	                TrackedMut::reborrow_mut(&mut engine.sink),
360	                engine.route.track(),
361	                context,
362	                args,
363	            ),
364	            FuncInner::Plugin(func) => {
365	                let inputs = args.all::<Bytes>()?;
366	                let output = func.call(inputs).at(args.span)?;
367	                args.finish()?;
368	                Ok(Value::Bytes(output))
369	            }
370	            FuncInner::With(with) => {
371	                args.items = with.1.items.iter().cloned().chain(args.items).collect();
372	                with.0.call(engine, context, args)
373	            }
374	        }
375	    }
376	
377	    /// The function's span.
378	    pub fn span(&self) -> Span {
379	        self.span
380	    }
381	
382	    /// Attach a span to this function if it doesn't already have one.
383	    pub fn spanned(mut self, span: Span) -> Self {
384	        if self.span.is_detached() {
385	            self.span = span;
386	        }
387	        self
388	    }
389	}
