391	#[scope]
392	impl Func {
393	    /// Returns a new function that has the given arguments pre-applied.
394	    #[func(since = "forever")]
395	    pub fn with(
396	        self,
397	        args: &mut Args,
398	        /// The arguments to apply to the function.
399	        #[external]
400	        #[variadic]
401	        arguments: Vec<Value>,
402	    ) -> Func {
403	        let span = self.span;
404	        Self {
405	            inner: FuncInner::With(Arc::new((self, args.take()))),
406	            span,
407	        }
408	    }
