410	    /// Returns a selector that filters for elements belonging to this function
411	    /// whose fields have the values of the given arguments.
412	    ///
413	    /// ```example
414	    /// #show heading.where(level: 2): set text(blue)
415	    /// = Section
416	    /// == Subsection
417	    /// === Sub-subsection
418	    /// ```
419	    #[func(since = "forever")]
420	    pub fn where_(
421	        self,
422	        args: &mut Args,
423	        /// The fields to filter for.
424	        #[variadic]
425	        #[external]
426	        fields: Vec<Value>,
427	    ) -> StrResult<Selector> {
428	        let fields = args.to_named();
429	        args.items.retain(|arg| arg.name.is_none());
430	
431	        let element = self
432	            .to_element()
433	            .ok_or("`where()` can only be called on element functions")?;
434	
435	        let fields = fields
436	            .into_iter()
437	            .map(|(key, value)| {
438	                element.field_id(&key).map(|id| (id, value)).ok_or_else(|| {
439	                    eco_format!(
440	                        "element `{}` does not have field `{}`",
441	                        element.name(),
442	                        key
443	                    )
444	                })
445	            })
446	            .collect::<StrResult<smallvec::SmallVec<_>>>()?;
447	
448	        Ok(element.where_(fields))
449	    }
450	}
