536	impl ParamInfo {
537	    /// Attempts to cast to a native parameter info.
538	    pub fn to_native(&self) -> Option<&'static NativeParamInfo> {
539	        match self {
540	            Self::Native(native) => Some(native),
541	            _ => None,
542	        }
