545	    /// The parameter's name, if any.
546	    pub fn name(&self) -> Option<&str> {
547	        match self {
548	            Self::Native(info) => Some(info.name),
549	            Self::Closure(info) => match &info.v {
550	                ClosureParamInfo::Pos { name } => name.as_deref(),
551	                ClosureParamInfo::Sink { name } => name.as_deref(),
552	                ClosureParamInfo::Named { name, .. } => Some(name),
