560	        match self {
561	            Self::Native(info) => info.default.map(|f| f()),
562	            Self::Closure(info) => match &info.v {
563	                ClosureParamInfo::Named { default, .. } => Some(default.clone()),
564	                _ => None,
565	            },
566	            Self::Plugin => None,
567	        }
568	    }
