572	        match self {
573	            Self::Native(info) => info.positional,
574	            Self::Closure(info) => matches!(
575	                &info.v,
576	                ClosureParamInfo::Pos { .. } | ClosureParamInfo::Sink { .. }
577	            ),
578	            Self::Plugin => true,
579	        }
580	    }
581	
582	    /// Whether the parameter is named.
583	    pub fn named(&self) -> bool {
584	        match self {
585	            Self::Native(info) => info.named,
586	            Self::Closure(info) => matches!(&info.v, ClosureParamInfo::Named { .. }),
587	            Self::Plugin => false,
588	        }
589	    }
590	
591	    /// Whether the parameter is variadic.
