600	    /// Whether the parameter is required.
601	    pub fn required(&self) -> bool {
602	        match self {
603	            Self::Native(info) => info.required,
604	            Self::Closure(info) => matches!(&info.v, ClosureParamInfo::Pos { .. }),
605	            Self::Plugin => false,
606	        }
607	    }
