713	/// Distinguishes between variants of closures.
714	#[derive(Debug, Hash)]
715	pub enum ClosureNode {
716	    /// A regular closure. Must always be castable to a `ast::Closure`.
717	    Closure(SyntaxNode),
718	    /// Synthetic closure used for `context` expressions. Can be any `ast::Expr`
719	    /// and has no parameters.
720	    Context(SyntaxNode),
721	}
722	
723	/// A user-defined closure.
724	#[derive(Debug, Hash)]
725	pub struct Closure {
726	    /// The closure's syntax node.
727	    pub node: ClosureNode,
728	    /// Default values of named parameters.
729	    pub defaults: Vec<Value>,
730	    /// Captured values from outer scopes.
731	    pub captured: Scope,
732	    /// The number of positional parameters in the closure.
733	    pub num_pos_params: usize,
734	}
735	
736	impl Closure {
737	    /// The name of the closure.
738	    pub fn name(&self) -> Option<&str> {
739	        match self.node {
740	            ClosureNode::Closure(ref node) => {
741	                node.cast::<ast::Closure>()?.name().map(|ident| ident.as_str())
742	            }
743	            ClosureNode::Context(_) => None,
744	        }
745	    }
746	
747	    /// Returns details about this closure's parameters.
748	    pub fn params(&self) -> impl Iterator<Item = Spanned<ClosureParamInfo>> {
749	        let params = match self.node {
750	            ClosureNode::Closure(ref node) => Some(
751	                node.cast::<ast::Closure>()
752	                    .expect("node to be an `ast::Closure`")
753	                    .params()
754	                    .children(),
755	            ),
756	            ClosureNode::Context(_) => None,
757	        };
758	
759	        let mut defaults = self.defaults.iter();
760	        params.into_iter().flatten().map(move |param| {
761	            let info = match param {
762	                ast::Param::Pos(pattern) => ClosureParamInfo::Pos {
763	                    name: match pattern {
764	                        ast::Pattern::Normal(ast::Expr::Ident(ident)) => {
765	                            Some(ident.get().clone())
766	                        }
767	                        _ => None,
768	                    },
769	                },
770	                ast::Param::Spread(spread) => ClosureParamInfo::Sink {
771	                    name: spread.sink_ident().map(|ident| ident.get().clone()),
772	                },
773	                ast::Param::Named(named) => ClosureParamInfo::Named {
774	                    name: named.name().get().clone(),
775	                    default: defaults.next().unwrap().clone(),
776	                },
777	            };
778	            Spanned::new(info, param.span())
779	        })
780	    }
781	}
