1	use heck::ToKebabCase;
2	use proc_macro2::TokenStream;
3	use quote::quote;
4	use syn::parse::{Parse, ParseStream};
5	use syn::{Ident, Result, parse_quote};
6	
7	use crate::util::{
8	    Since, determine_name_and_title, documentation, foundations, has_attr, kw, oneliner,
9	    parse_attr, parse_flag, parse_key_value, parse_string, parse_string_array,
10	    quote_option, validate_attrs,
11	};
12	
13	/// Expand the `#[func]` macro.
14	pub fn func(stream: TokenStream, item: &syn::ItemFn) -> Result<TokenStream> {
15	    let func = parse(stream, item)?;
16	    Ok(create(&func, item))
17	}
18	
19	/// Details about a function.
20	struct Func {
21	    /// The function's name as exposed to Typst.
22	    name: String,
23	    /// The function's title case name.
24	    title: String,
25	    /// The version of Typst the function was introduced in.
26	    since: Option<Since>,
27	    /// Whether this function has an associated scope defined by the `#[scope]` macro.
28	    scope: bool,
29	    /// Whether this function is a constructor.
30	    constructor: bool,
31	    /// A list of alternate search terms for this function.
32	    keywords: Vec<String>,
33	    /// The parent type of this function.
34	    ///
35	    /// Used for functions in a scope.
36	    parent: Option<syn::Type>,
37	    /// Whether this function is contextual.
38	    contextual: bool,
39	    /// The documentation for this function as a string.
40	    docs: String,
41	    /// The function's visibility.
42	    vis: syn::Visibility,
43	    /// The name for this function given in Rust.
44	    ident: Ident,
45	    /// Special parameters provided by the runtime.
46	    special: SpecialParams,
47	    /// The list of parameters for this function.
48	    params: Vec<Param>,
49	    /// The return type of this function.
50	    returns: syn::Type,
51	}
52	
53	/// Special parameters provided by the runtime.
54	#[derive(Default)]
55	struct SpecialParams {
56	    /// The receiver (`self`) parameter.
57	    self_: Option<Param>,
58	    /// The parameter named `engine`, of type `&mut Engine`.
59	    engine: bool,
60	    /// The parameter named `context`, of type `Tracked<Context>`.
61	    context: bool,
62	    /// The parameter named `args`, of type `&mut Args`.
63	    args: bool,
64	    /// The parameter named `span`, of type `Span`.
65	    span: bool,
66	}
67	
68	/// Details about a function parameter.
69	struct Param {
70	    /// The binding for this parameter.
71	    binding: Binding,
72	    /// The name of the parameter as defined in Rust.
73	    ident: Ident,
74	    /// The type of the parameter.
75	    ty: syn::Type,
76	    /// The name of the parameter as defined in Typst.
77	    name: String,
78	    /// The documentation for this parameter as a string.
79	    docs: String,
80	    /// Whether this parameter is named.
81	    named: bool,
82	    /// Whether this parameter is variadic; that is, has its values
83	    /// taken from a variable number of arguments.
84	    variadic: bool,
85	    /// Whether this parameter exists only in documentation.
86	    external: bool,
87	    /// The default value for this parameter.
88	    default: Option<syn::Expr>,
89	}
90	
91	/// How a parameter is bound.
92	enum Binding {
93	    /// Normal parameter.
94	    Owned,
95	    /// `&self`.
96	    Ref,
97	    /// `&mut self`.
98	    RefMut,
99	}
100	
101	/// The `..` in `#[func(..)]`.
102	pub struct Meta {
103	    /// Whether this function has an associated scope defined by the `#[scope]` macro.
104	    pub scope: bool,
105	    /// Whether this function is contextual.
106	    pub contextual: bool,
107	    /// The function's name as exposed to Typst.
108	    pub name: Option<String>,
109	    /// The function's title case name.
110	    pub title: Option<String>,
111	    /// The version of Typst the function was introduced in.
112	    pub since: Option<Since>,
113	    /// Whether this function is a constructor.
114	    pub constructor: bool,
115	    /// A list of alternate search terms for this function.
116	    pub keywords: Vec<String>,
117	    /// The parent type of this function.
118	    ///
119	    /// Used for functions in a scope.
120	    pub parent: Option<syn::Type>,
121	}
122	
123	impl Parse for Meta {
124	    fn parse(input: ParseStream) -> Result<Self> {
125	        Ok(Self {
126	            scope: parse_flag::<kw::scope>(input)?,
127	            contextual: parse_flag::<kw::contextual>(input)?,
128	            name: parse_string::<kw::name>(input)?,
129	            title: parse_string::<kw::title>(input)?,
130	            constructor: parse_flag::<kw::constructor>(input)?,
131	            since: parse_key_value::<kw::since, Since>(input)?,
132	            keywords: parse_string_array::<kw::keywords>(input)?,
133	            parent: parse_key_value::<kw::parent, _>(input)?,
134	        })
135	    }
136	}
137	
138	/// Parse details about the function from the fn item.
139	fn parse(stream: TokenStream, item: &syn::ItemFn) -> Result<Func> {
140	    let meta: Meta = syn::parse2(stream)?;
141	    let (name, title) =
142	        determine_name_and_title(meta.name, meta.title, &item.sig.ident, None)?;
143	
144	    let docs = documentation(&item.attrs);
145	
146	    let mut special = SpecialParams::default();
147	    let mut params = vec![];
148	    for input in &item.sig.inputs {
149	        parse_param(&mut special, &mut params, meta.parent.as_ref(), input)?;
150	    }
151	
152	    let returns = match &item.sig.output {
153	        syn::ReturnType::Default => parse_quote! { () },
154	        syn::ReturnType::Type(_, ty) => ty.as_ref().clone(),
155	    };
156	
157	    if meta.parent.is_some() && meta.scope {
158	        bail!(item, "scoped function cannot have a scope");
159	    }
160	
161	    Ok(Func {
162	        name,
163	        title,
164	        since: meta.since,
165	        scope: meta.scope,
166	        constructor: meta.constructor,
167	        keywords: meta.keywords,
168	        parent: meta.parent,
169	        contextual: meta.contextual,
170	        docs,
171	        vis: item.vis.clone(),
172	        ident: item.sig.ident.clone(),
173	        special,
174	        params,
175	        returns,
176	    })
177	}
178	
179	/// Parse details about a function parameter.
180	fn parse_param(
181	    special: &mut SpecialParams,
182	    params: &mut Vec<Param>,
183	    parent: Option<&syn::Type>,
184	    input: &syn::FnArg,
185	) -> Result<()> {
186	    let typed = match input {
187	        syn::FnArg::Receiver(recv) => {
188	            let mut binding = Binding::Owned;
189	            if recv.reference.is_some() {
190	                if recv.mutability.is_some() {
191	                    binding = Binding::RefMut;
192	                } else {
193	                    binding = Binding::Ref;
194	                }
195	            }
196	
197	            special.self_ = Some(Param {
198	                binding,
199	                ident: syn::Ident::new("self_", recv.self_token.span),
200	                ty: match parent {
201	                    Some(ty) => ty.clone(),
202	                    None => bail!(recv, "explicit parent type required"),
203	                },
204	                name: "self".into(),
205	                docs: documentation(&recv.attrs),
206	                named: false,
207	                variadic: false,
208	                external: false,
209	                default: None,
210	            });
211	            return Ok(());
212	        }
213	        syn::FnArg::Typed(typed) => typed,
214	    };
215	
216	    let syn::Pat::Ident(syn::PatIdent { by_ref: None, mutability: None, ident, .. }) =
217	        &*typed.pat
218	    else {
219	        bail!(typed.pat, "expected identifier");
220	    };
221	
222	    match ident.to_string().as_str() {
223	        "engine" => special.engine = true,
224	        "context" => special.context = true,
225	        "args" => special.args = true,
226	        "span" => special.span = true,
227	        _ => {
228	            let mut attrs = typed.attrs.clone();
229	            params.push(Param {
230	                binding: Binding::Owned,
231	                ident: ident.clone(),
232	                ty: (*typed.ty).clone(),
233	                name: ident.to_string().to_kebab_case(),
234	                docs: documentation(&attrs),
235	                named: has_attr(&mut attrs, "named"),
236	                variadic: has_attr(&mut attrs, "variadic"),
237	                external: has_attr(&mut attrs, "external"),
238	                default: parse_attr(&mut attrs, "default")?.map(|expr| {
239	                    expr.unwrap_or_else(
240	                        || parse_quote! { ::std::default::Default::default() },
241	                    )
242	                }),
243	            });
244	            validate_attrs(&attrs)?;
245	        }
246	    }
247	
248	    Ok(())
249	}
250	
251	/// Produce the function's definition.
252	fn create(func: &Func, item: &syn::ItemFn) -> TokenStream {
253	    let Func { docs, vis, ident, .. } = func;
254	    let item = rewrite_fn_item(item);
255	    let ty = create_func_ty(func);
256	    let data = create_func_data(func);
257	    let oneliner = oneliner(docs);
258	
259	    let creator = if ty.is_some() {
260	        quote! {
261	            impl #foundations::NativeFunc for #ident {
262	                fn data() -> &'static #foundations::NativeFuncData {
263	                    static DATA: #foundations::NativeFuncData = #data;
264	                    &DATA
265	                }
266	            }
267	        }
268	    } else {
