11	pub fn scope(stream: TokenStream, item: syn::Item) -> Result<TokenStream> {
12	    let meta: Meta = syn::parse2(stream)?;
13	    let syn::Item::Impl(mut item) = item else {
14	        bail!(item, "expected module or impl item");
15	    };
16	
17	    let self_ty = &item.self_ty;
